  "keywords": [
    "nameless-dhamma",
    "launcher",
    "research",
    "critic"
  ],
  "extensions": {
    "com.openai": {
      "interface": {
        "displayName": "ND Research Critic",
        "shortDescription": "Mandatory closure Child through True Research",
        "longDescription": "Mandatory final adversarial review Child for substantive True Research results.",
        "developerName": "Nameless Dhamma",
        "category": "Productivity",
        "defaultPrompt": [
          "Use ND Research Critic for this task."
        ]
      }
    }
  }
}
